Type: C<String>

Required. The client-assigned sink identifier, unique within the project.

For example: `"my-syslog-errors-to-pubsub"`. Sink identifiers are limited
to 100 characters and can include only the following characters: upper and
lower-case alphanumeric characters, underscores, hyphens, and periods.
First character has to be alphanumeric.

=item * C<< $msg->destination() >> / C<< $msg->destination($value) >>

Type: C<String>

Required. The export destination:

    "storage.googleapis.com/[GCS_BUCKET]"
    "bigquery.googleapis.com/projects/[PROJECT_ID]/datasets/[DATASET]"
    "pubsub.googleapis.com/projects/[PROJECT_ID]/topics/[TOPIC_ID]"

The sink's `writer_identity`, set when the sink is created, must have
permission to write to the destination or else the log entries are not
exported. For more information, see
[Exporting Logs with
Sinks](https://cloud.google.com/logging/docs/api/tasks/exporting-logs).

=item * C<< $msg->filter() >> / C<< $msg->filter($value) >>

Type: C<String>

Optional. An [advanced logs
filter](https://cloud.google.com/logging/docs/view/advanced-queries). The
only exported log entries are those that are in the resource owning the
sink and that match the filter.

For example:

  `logName="projects/[PROJECT_ID]/logs/[LOG_ID]" AND severity>=ERROR`

=item * C<< $msg->description() >> / C<< $msg->description($value) >>

Type: C<String>

Optional. A description of this sink.

The maximum length of the description is 8000 characters.

=item * C<< $msg->disabled() >> / C<< $msg->disabled($value) >>

Type: C<Bool>

Optional. If set to true, then this sink is disabled and it does not export
any log entries.

=item * C<< $msg->exclusions() >> / C<< $msg->exclusions($value) >>

Type: C<Message> (L<Google::Logging::V2::LoggingConfig::LogExclusion>)

Optional. Log entries that match any of these exclusion filters will not be
exported.

If a log entry is matched by both `filter` and one of `exclusion_filters`
it will not be exported.

=item * C<< $msg->output_version_format() >> / C<< $msg->output_version_format($value) >>

Type: C<Enum> (L<Google::Logging::V2::LogSink::VersionFormat>)

Deprecated. This field is unused.

=item * C<< $msg->writer_identity() >> / C<< $msg->writer_identity($value) >>

Type: C<String>

Output only. An IAM identity&mdash;a service account or group&mdash;under
which Cloud Logging writes the exported log entries to the sink's
destination. This field is either set by specifying
`custom_writer_identity` or set automatically by
[sinks.create][google.logging.v2.ConfigServiceV2.CreateSink] and
[sinks.update][google.logging.v2.ConfigServiceV2.UpdateSink] based on the
value of `unique_writer_identity` in those methods.

Until you grant this identity write-access to the destination, log entry
exports from this sink will fail. For more information, see [Granting
Access for a
Resource](https://cloud.google.com/iam/docs/granting-roles-to-service-accounts#granting_access_to_a_service_account_for_a_resource).
Consult the destination service's documentation to determine the
appropriate IAM roles to assign to the identity.

Sinks that have a destination that is a log bucket in the same project as
the sink cannot have a writer_identity and no additional permissions are
required.

=item * C<< $msg->include_children() >> / C<< $msg->include_children($value) >>

Type: C<Bool>

Optional. This field applies only to sinks owned by organizations and
folders. If the field is false, the default, only the logs owned by the
sink's parent resource are available for export. If the field is true, then
log entries from all the projects, folders, and billing accounts contained
in the sink's parent resource are also available for export. Whether a
particular log entry from the children is exported depends on the sink's
filter expression.

For example, if this field is true, then the filter
`resource.type=gce_instance` would export all Compute Engine VM instance
log entries from all projects in the sink's parent.

To only export entries from certain child projects, filter on the project
part of the log name:

  logName:("projects/test-project1/" OR "projects/test-project2/") AND
  resource.type=gce_instance

=item * C<< $msg->bigquery_options() >> / C<< $msg->bigquery_options($value) >>

Type: C<Message> (L<Google::Logging::V2::LoggingConfig::BigQueryOptions>)

Optional. Options that affect sinks exporting data to BigQuery.

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. The creation timestamp of the sink.

This field may not be present for older sinks.

