be updated. A field will be overwritten if and only if it is in the update
mask. Output only fields cannot be updated.

See [FieldMask][google.protobuf.FieldMask] for more information.

For example: `"updateMask=kmsKeyName"`

=back

=head2 Google::Logging::V2::LoggingConfig::CmekSettings

Describes the customer-managed encryption key (CMEK) settings associated with
a project, folder, organization, billing account, or flexible resource.

Note: CMEK for the Log Router can currently only be configured for Google
Cloud organizations. Once configured, it applies to all projects and folders
in the Google Cloud organization.

See [Enabling CMEK for Log
Router](https://cloud.google.com/logging/docs/routing/managed-encryption) for
more information.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. The resource name of the CMEK settings.

=item * C<< $msg->kms_key_name() >> / C<< $msg->kms_key_name($value) >>

Type: C<String>

The resource name for the configured Cloud KMS key.

KMS key name format:

    "projects/[PROJECT_ID]/locations/[LOCATION]/keyRings/[KEYRING]/cryptoKeys/[KEY]"

For example:

  `"projects/my-project/locations/us-central1/keyRings/my-ring/cryptoKeys/my-key"`



To enable CMEK for the Log Router, set this field to a valid
`kms_key_name` for which the associated service account has the required
cloudkms.cryptoKeyEncrypterDecrypter roles assigned for the key.

The Cloud KMS key used by the Log Router can be updated by changing the
`kms_key_name` to a new valid key name or disabled by setting the key name
to an empty string. Encryption operations that are in progress will be
completed with the key that was in use when they started. Decryption
operations will be completed using the key that was used at the time of
encryption unless access to that key has been revoked.

To disable CMEK for the Log Router, set this field to an empty string.

See [Enabling CMEK for Log
Router](https://cloud.google.com/logging/docs/routing/managed-encryption)
for more information.

=item * C<< $msg->kms_key_version_name() >> / C<< $msg->kms_key_version_name($value) >>

Type: C<String>

The CryptoKeyVersion resource name for the configured Cloud KMS key.

KMS key name format:

    "projects/[PROJECT_ID]/locations/[LOCATION]/keyRings/[KEYRING]/cryptoKeys/[KEY]/cryptoKeyVersions/[VERSION]"

For example:

  `"projects/my-project/locations/us-central1/keyRings/my-ring/cryptoKeys/my-key/cryptoKeyVersions/1"`

This is a read-only field used to convey the specific configured
CryptoKeyVersion of `kms_key` that has been configured. It will be
populated in cases where the CMEK settings are bound to a single key
version.

If this field is populated, the `kms_key` is tied to a specific
CryptoKeyVersion.

=item * C<< $msg->service_account_id() >> / C<< $msg->service_account_id($value) >>

Type: C<String>

Output only. The service account that will be used by the Log Router to
access your Cloud KMS key.

Before enabling CMEK for Log Router, you must first assign the
cloudkms.cryptoKeyEncrypterDecrypter role to the service account that
the Log Router will use to access your Cloud KMS key. Use
[GetCmekSettings][google.logging.v2.ConfigServiceV2.GetCmekSettings] to
obtain the service account ID.

See [Enabling CMEK for Log
Router](https://cloud.google.com/logging/docs/routing/managed-encryption)
for more information.

=back

=head2 Google::Logging::V2::LoggingConfig::GetSettingsRequest

The parameters to
[GetSettings][google.logging.v2.ConfigServiceV2.GetSettings].

See [Enabling CMEK for Log
Router](https://cloud.google.com/logging/docs/routing/managed-encryption) for
more information.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Required. The resource for which to retrieve settings.

    "projects/[PROJECT_ID]/settings"
    "organizations/[ORGANIZATION_ID]/settings"
    "billingAccounts/[BILLING_ACCOUNT_ID]/settings"
    "folders/[FOLDER_ID]/settings"

For example:

  `"organizations/12345/settings"`

Note: Settings for the Log Router can be get for Google Cloud projects,
folders, organizations and billing accounts. Currently it can only be
configured for organizations. Once configured for an organization, it
applies to all projects and folders in the Google Cloud organization.

=back

