=head2 Google::Logging::V2::LoggingConfig::Settings

Describes the settings associated with a project, folder, organization,
billing account, or flexible resource.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Output only. The resource name of the settings.

=item * C<< $msg->kms_key_name() >> / C<< $msg->kms_key_name($value) >>

Type: C<String>

Optional. The resource name for the configured Cloud KMS key.

KMS key name format:

    "projects/[PROJECT_ID]/locations/[LOCATION]/keyRings/[KEYRING]/cryptoKeys/[KEY]"

For example:

  `"projects/my-project/locations/us-central1/keyRings/my-ring/cryptoKeys/my-key"`



To enable CMEK for the Log Router, set this field to a valid
`kms_key_name` for which the associated service account has the required
`roles/cloudkms.cryptoKeyEncrypterDecrypter` role assigned for the key.

The Cloud KMS key used by the Log Router can be updated by changing the
`kms_key_name` to a new valid key name. Encryption operations that are in
progress will be completed with the key that was in use when they started.
Decryption operations will be completed using the key that was used at the
time of encryption unless access to that key has been revoked.

To disable CMEK for the Log Router, set this field to an empty string.

See [Enabling CMEK for Log
Router](https://cloud.google.com/logging/docs/routing/managed-encryption)
for more information.

=item * C<< $msg->kms_service_account_id() >> / C<< $msg->kms_service_account_id($value) >>

Type: C<String>

Output only. The service account that will be used by the Log Router to
access your Cloud KMS key.

Before enabling CMEK for Log Router, you must first assign the role
`roles/cloudkms.cryptoKeyEncrypterDecrypter` to the service account that
the Log Router will use to access your Cloud KMS key. Use
[GetSettings][google.logging.v2.ConfigServiceV2.GetSettings] to
obtain the service account ID.

See [Enabling CMEK for Log
Router](https://cloud.google.com/logging/docs/routing/managed-encryption)
for more information.

=item * C<< $msg->storage_location() >> / C<< $msg->storage_location($value) >>

Type: C<String>

Optional. The Cloud region that will be used for _Default and _Required log
buckets for newly created projects and folders. For example `europe-west1`.
This setting does not affect the location of custom log buckets.

=item * C<< $msg->disable_default_sink() >> / C<< $msg->disable_default_sink($value) >>

Type: C<Bool>

Optional. If set to true, the _Default sink in newly created projects and
folders will created in a disabled state. This can be used to automatically
disable log ingestion if there is already an aggregated sink configured in
the hierarchy. The _Default sink can be re-enabled manually if needed.

=back

=head2 Google::Logging::V2::LoggingConfig::CopyLogEntriesRequest

The parameters to CopyLogEntries.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Required. Log bucket from which to copy log entries.

For example:

  `"projects/my-project/locations/global/buckets/my-source-bucket"`

=item * C<< $msg->filter() >> / C<< $msg->filter($value) >>

Type: C<String>

Optional. A filter specifying which log entries to copy. The filter must be
no more than 20k characters. An empty filter matches all log entries.

=item * C<< $msg->destination() >> / C<< $msg->destination($value) >>

Type: C<String>

Required. Destination to which to copy log entries.

=back

